TplValue makeStringValue(const std::string &name, const std::string &value)
{
    TplValue out{};
    out.name = name;
    out.type = ValueType::str;
    out.stringValue = value;
    return out;
}

ThingBox makeBox(const double x1, const double y1, const double z1, const double x2, const double y2, const double z2)
{
    ThingBox box{};
    box.Set(x1, y1, z1, x2, y2, z2);
    return box;
}

bool sectorContainsInteriorPointForTest(const Sector& sector, const TVector& point)
{
    for (const Surface& surface : sector.surfaces)
    {
        if (surface.vertices.empty())
        {
            continue;
        }

        const std::int32_t v0Index = surface.vertices[0];
        if (v0Index < 0 || static_cast<std::size_t>(v0Index) >= sector.vertices.size())
        {
            return false;
        }

        TVector normal = surface.normal;
        if (normal.length() == 0.0)
        {
            normal = level::surfaceCalcNormalNewell(sector, surface);
        }
        if (normal.normalize() == 0.0)
        {
            continue;
        }

        const Vertex& v0 = sector.vertices[static_cast<std::size_t>(v0Index)];
        if (normal.dot(point.x - v0.x, point.y - v0.y, point.z - v0.z) <= 0.001)
        {
            return false;
        }
    }

    return true;
}

bool sectorHasInteriorSampleInsideForTest(const Sector& source, const Sector& container)
{
    if (sectorContainsInteriorPointForTest(container, level::sectorCalcCenter(source)))
    {
        return true;
    }

    for (const Surface& surface : source.surfaces)
    {
        TVector surfaceSum{};
        std::int32_t validVertexCount = 0;

        for (std::size_t i = 0; i < surface.vertices.size(); ++i)
        {
            const std::int32_t currentIndex = surface.vertices[i];
            if (currentIndex < 0 || static_cast<std::size_t>(currentIndex) >= source.vertices.size())
            {
                continue;
            }

            const Vertex& currentVertex = source.vertices[static_cast<std::size_t>(currentIndex)];
            const TVector current{ currentVertex.x, currentVertex.y, currentVertex.z };
            surfaceSum = surfaceSum + current;
            ++validVertexCount;

            if (sectorContainsInteriorPointForTest(container, current))
            {
                return true;
            }

            if (surface.vertices.size() < 2)
            {
                continue;
            }

            const std::int32_t nextIndex = surface.vertices[(i + 1) % surface.vertices.size()];
            if (nextIndex < 0 || static_cast<std::size_t>(nextIndex) >= source.vertices.size())
            {
                continue;
            }

            const Vertex& nextVertex = source.vertices[static_cast<std::size_t>(nextIndex)];
            const TVector midpoint{
                (currentVertex.x + nextVertex.x) * 0.5,
                (currentVertex.y + nextVertex.y) * 0.5,
                (currentVertex.z + nextVertex.z) * 0.5,
            };
            if (sectorContainsInteriorPointForTest(container, midpoint))
            {
                return true;
            }
        }

        if (validVertexCount <= 0)
        {
            continue;
        }

        const TVector surfaceCenter = surfaceSum * (1.0 / static_cast<double>(validVertexCount));
        if (sectorContainsInteriorPointForTest(container, surfaceCenter))
        {
            return true;
        }
    }

    return false;
}

bool sectorInteriorOverlapsForTest(const Sector& sector, const Sector& container)
{
    if (sector.vertices.empty() || container.vertices.empty())
    {
        return false;
    }

    if (!level::doBoxesIntersect(level::sectorCalcBBox(sector), level::sectorCalcBBox(container)))
    {
        return false;
    }

    const auto sectorsOverlap = [](const Sector& a, const Sector& b)
    {
        const auto surfacesDoNotSeparate = [](const Sector& source, const Sector& other)
        {
            for (const Surface& surface : source.surfaces)
            {
                if (surface.vertices.empty())
                {
                    continue;
                }

                const std::int32_t v0Index = surface.vertices[0];
                if (v0Index < 0 || static_cast<std::size_t>(v0Index) >= source.vertices.size())
                {
                    return false;
                }

                TVector normal = surface.normal;
                if (normal.length() == 0.0)
                {
                    normal = level::surfaceCalcNormalNewell(source, surface);
                }
                if (normal.normalize() == 0.0)
                {
                    continue;
                }

                const Vertex& v0 = source.vertices[static_cast<std::size_t>(v0Index)];
                bool hasVertexInsidePlane = false;
                for (const Vertex& vertex : other.vertices)
                {
                    if (normal.dot(vertex.x - v0.x, vertex.y - v0.y, vertex.z - v0.z) > 0.01)
                    {
                        hasVertexInsidePlane = true;
                        break;
                    }
                }

                if (!hasVertexInsidePlane)
                {
                    return false;
                }
            }

            return true;
        };

        return surfacesDoNotSeparate(a, b) && surfacesDoNotSeparate(b, a);
    };

    return sectorsOverlap(sector, container)
        || sectorHasInteriorSampleInsideForTest(sector, container)
        || sectorHasInteriorSampleInsideForTest(container, sector);
}

bool previewSelectionOverlapsSectorInterior(
    const sed::ui::sector::SectorJoinPreviewResult& preview,
    const Sector& target)
{
    return std::any_of(
        preview.selection.sectors.begin(),
        preview.selection.sectors.end(),
        [&preview, &target](const std::int32_t sectorIndex)
        {
            if (sectorIndex < 0 || static_cast<std::size_t>(sectorIndex) >= preview.level.sectors.size())
            {
                return false;
            }

            return sectorInteriorOverlapsForTest(
                preview.level.sectors[static_cast<std::size_t>(sectorIndex)],
                target);
        });
}

bool previewHasMaterialInsideSector(
    const sed::ui::sector::SectorJoinPreviewResult& preview,
    const Sector& target,
    const std::int32_t material)
{
    return std::any_of(
        preview.level.sectors.begin(),
        preview.level.sectors.end(),
        [&target, material](const Sector& sector)
        {
            const bool usesMaterial = std::any_of(
                sector.surfaces.begin(),
                sector.surfaces.end(),
                [material](const Surface& surface)
                {
                    return surface.nMat == material;
                });

            return usesMaterial && sectorInteriorOverlapsForTest(sector, target);
        });
}

sed::thing::SnapConnector makeRailConnector(const TVector &railA, const TVector &railB, const TVector &tangent)
{
    sed::thing::SnapConnector connector{};
    connector.railA = railA;
    connector.railB = railB;
    connector.position = (railA + railB).Scaled(0.5);
    connector.tangent = tangent;
    return connector;
}

TVector midpoint(const TVector &a, const TVector &b)
{
    return (a + b).Scaled(0.5);
}

TVector snappedMovingRailCenter(const sed::thing::RailPairSnapCandidate &candidate)
{
    return candidate.origin + candidate.rotation.TransformVector(midpoint(candidate.movingRailA, candidate.movingRailB));
}

TVector targetRailCenter(const sed::thing::RailPairSnapCandidate &candidate)
{
    return midpoint(candidate.targetRailA, candidate.targetRailB);
}

bool hasCenterlineRailJoin(const sed::thing::SnapConnector &moving, const sed::thing::SnapConnector &anchor, const TMatrix43 &anchorXf,
                           const TVector &desiredMovingTangent, const double minimumTangentDot, const double maxCenterDistance)
{
    const TVector basePyr{};
    const TMatrix43 baseRot = TMatrix43::Create(TVector::zero, basePyr);
    const std::vector<sed::thing::RailPairSnapCandidate> candidates =
        sed::thing::buildRailPairSnapCandidates(moving, anchor, basePyr, baseRot, anchorXf, desiredMovingTangent, true, minimumTangentDot);

    for (const sed::thing::RailPairSnapCandidate &candidate : candidates)
    {
        if (candidate.tangentDot >= minimumTangentDot && snappedMovingRailCenter(candidate).Distance(targetRailCenter(candidate)) <= maxCenterDistance)
        {
            return true;
        }
    }
    return false;
}

bool closeRotationMatrix(const TMatrix43 &a, const TMatrix43 &b, const double eps = 1e-6)
{
    return closeVec(a.rvec, b.rvec, eps) && closeVec(a.lvec, b.lvec, eps) && closeVec(a.uvec, b.uvec, eps);
}

bool closePoint(const QPointF &a, const QPointF &b, const qreal eps = 1.0e-6)
{
    return std::abs(a.x() - b.x()) <= eps && std::abs(a.y() - b.y()) <= eps;
}

Level makeSurfaceExtrudePreviewLevel(const bool rectangular)
{
    Level level{};
    level.kind = ProjectType::JKDF2;
    level.masterCMP = "master.cmp";

    Sector &sector = level.newSector();
    sector.addVertex(0.0, 0.0, 0.0);
    sector.addVertex(2.0, 0.0, 0.0);
    if (rectangular)
    {
        sector.addVertex(2.0, 2.0, 0.0);
        sector.addVertex(0.0, 2.0, 0.0);
    }
    else
    {
        sector.addVertex(0.5, 1.0, 0.0);
    }

    Surface surface{};
    surface.material = "test.mat";
    surface.geo = static_cast<std::int32_t>(TGeoMode::Texture);
    surface.vertices = rectangular
        ? std::vector<std::int32_t>{0, 1, 2, 3}
        : std::vector<std::int32_t>{0, 1, 2};
    surface.texVertices = std::vector<TexVertex>(surface.vertices.size());
    sector.addSurface(std::move(surface));

    return level;
}

void touchFile(const std::filesystem::path &path)
{
    std::filesystem::create_directories(path.parent_path());
    std::ofstream output(path, std::ios::binary);
    output.put('\0');
}

void appendAudioFixtureText(
    std::vector<std::byte>& bytes,
    const std::string_view text)
{
    for (const char value : text)
    {
        bytes.push_back(static_cast<std::byte>(value));
    }
}

void appendAudioFixtureU16Le(
    std::vector<std::byte>& bytes,
    const std::uint16_t value)
{
    bytes.push_back(static_cast<std::byte>(value & 0xFFU));
    bytes.push_back(static_cast<std::byte>((value >> 8U) & 0xFFU));
}

void appendAudioFixtureU16Be(
    std::vector<std::byte>& bytes,
    const std::uint16_t value)
{
    bytes.push_back(static_cast<std::byte>((value >> 8U) & 0xFFU));
    bytes.push_back(static_cast<std::byte>(value & 0xFFU));
}

void appendAudioFixtureU32Le(
    std::vector<std::byte>& bytes,
    const std::uint32_t value)
{
    bytes.push_back(static_cast<std::byte>(value & 0xFFU));
    bytes.push_back(static_cast<std::byte>((value >> 8U) & 0xFFU));
    bytes.push_back(static_cast<std::byte>((value >> 16U) & 0xFFU));
    bytes.push_back(static_cast<std::byte>((value >> 24U) & 0xFFU));
}

std::vector<std::byte> makeWavPreviewPcm16Fixture(
    const std::uint16_t channelCount,
    const std::uint32_t sampleRate,
    const std::uint32_t frameCount)
{
    const std::uint16_t blockAlign = static_cast<std::uint16_t>(channelCount * 2U);
    const std::uint32_t dataSize = frameCount * blockAlign;

    std::vector<std::byte> bytes;
    bytes.reserve(44U + dataSize);
    appendAudioFixtureText(bytes, "RIFF");
    appendAudioFixtureU32Le(bytes, 36U + dataSize);
    appendAudioFixtureText(bytes, "WAVEfmt ");
    appendAudioFixtureU32Le(bytes, 16U);
    appendAudioFixtureU16Le(bytes, 1U);
    appendAudioFixtureU16Le(bytes, channelCount);
    appendAudioFixtureU32Le(bytes, sampleRate);
    appendAudioFixtureU32Le(bytes, sampleRate * blockAlign);
    appendAudioFixtureU16Le(bytes, blockAlign);
    appendAudioFixtureU16Le(bytes, 16U);
    appendAudioFixtureText(bytes, "data");
    appendAudioFixtureU32Le(bytes, dataSize);
    bytes.resize(44U + dataSize);
    return bytes;
}

std::vector<std::byte> makeWavPreviewIndyWvFixture()
{
    std::vector<std::byte> bytes;
    appendAudioFixtureText(bytes, "INDYWV");
    appendAudioFixtureU32Le(bytes, 11'025U);
    appendAudioFixtureU32Le(bytes, 16U);
    appendAudioFixtureU32Le(bytes, 1U);
    appendAudioFixtureU32Le(bytes, 8U);
    appendAudioFixtureU32Le(bytes, 0U);

    appendAudioFixtureU32Le(bytes, 8U);
    bytes.push_back(std::byte{0xFF});
    appendAudioFixtureU16Be(bytes, 0x1111U);
    bytes.push_back(std::byte{0x64});
    appendAudioFixtureU16Be(bytes, 0x2222U);
    appendAudioFixtureText(bytes, "WVSM");
    appendAudioFixtureU16Be(bytes, 7U);
    bytes.push_back(std::byte{});
    bytes.insert(bytes.end(), 4U, std::byte{0x01});
    return bytes;
}

bool textBlockHasForeground(const QTextBlock &block, const QColor &color)
{
    if (!block.isValid() || !block.layout())
    {
        return false;
    }

    for (const QTextLayout::FormatRange &range : block.layout()->formats())
    {
        const QBrush brush = range.format.foreground();
        if (brush.style() != Qt::NoBrush && brush.color() == color)
        {
            return true;
        }
    }
    return false;
}

QColor textBlockForegroundAt(const QTextBlock& block, const int column)
{
    if (!block.isValid() || !block.layout())
    {
        return {};
    }
    for (const QTextLayout::FormatRange& range : block.layout()->formats())
    {
        if (column >= range.start && column < range.start + range.length)
        {
            return range.format.foreground().color();
        }
    }
    return {};
}

