    {
        for (const double angle : {-1e-15,0.0,1e-15})
        for (int component = 0; component < 3; ++component)
        {
            TVector input{};
            if (component == 0) input.pitch = angle;
            if (component == 1) input.yaw = angle;
            if (component == 2) input.roll = angle;
            const TVector actual = sed::ui::transform::extractPYRCreateRotateCompatible(TMatrix43::CreateRotate(input));
            const double result = component == 0 ? actual.pitch : component == 1 ? actual.yaw : actual.roll;
            check(angle == 0.0 ? result == 0.0 : std::abs(result-angle) <= std::abs(angle)*1e-14,
                "rotation extraction preserves signed tiny authored angles and exact identity without adding 180 degrees");
        }
        // Independent elementary rotations verify the pose, including the pole
        // where equivalent Euler spellings are intentionally not unique.
        const auto rotate = [](TVector point, const TVector& pyr)
        {
            const double p = pyr.pitch*std::numbers::pi/180.0;
            const double y = pyr.yaw*std::numbers::pi/180.0;
            const double r = pyr.roll*std::numbers::pi/180.0;
            point = TVector{point.x*std::cos(r)+point.z*std::sin(r),point.y,-point.x*std::sin(r)+point.z*std::cos(r)};
            point = TVector{point.x,point.y*std::cos(p)-point.z*std::sin(p),point.y*std::sin(p)+point.z*std::cos(p)};
            return TVector{point.x*std::cos(y)-point.y*std::sin(y),point.x*std::sin(y)+point.y*std::cos(y),point.z};
        };
        for (const double pitch : {-90.0,-89.99999999,-89.99999,89.99999,89.99999999,90.0})
        for (const double yaw : {-35.0,35.0})
        for (const double roll : {-17.0,17.0})
        for (const double scale : {1e-6,1.0,1e6})
        {
            const TVector input{pitch,yaw,roll};
            const TVector actual = sed::ui::transform::extractPYRCreateRotateCompatible(TMatrix43::CreateRotate(input));
            bool equivalent = true;
            for (const TVector& axis : std::array<TVector,3>{TVector{scale,0,0},TVector{0,scale,0},TVector{0,0,scale}})
            {
                const TVector error = rotate(axis,actual)-rotate(axis,input);
                equivalent = equivalent && std::hypot(error.x,error.y,error.z) <= scale*32.0*std::numeric_limits<double>::epsilon();
            }
            check(equivalent,"rotation extraction preserves actual near-pole pose across pitch signs, yaw/roll signs and geometry scales");
        }
        for (const double yaw : {-180.0,std::nextafter(-180.0,0.0),0.0,std::nextafter(180.0,0.0),180.0})
        {
            const TVector input{0,yaw,0};
            const TVector actual = sed::ui::transform::extractPYRCreateRotateCompatible(TMatrix43::CreateRotate(input));
            const TVector error = rotate(TVector{1,0,0},actual)-rotate(TVector{1,0,0},input);
            check(actual.yaw >= -180.0 && actual.yaw < 180.0
                    && std::hypot(error.x,error.y,error.z) <= 16.0*std::numeric_limits<double>::epsilon(),
                "rotation extraction preserves boundary pose with canonical half-open angles");
        }
    }

