        check(sed::ui::viewport::isThingPlacementTemplateDropEvent(QEvent::Drop), "thing_placement_drop accepts drop event type");
        check(!sed::ui::viewport::isThingPlacementTemplateDropEvent(QEvent::MouseMove), "thing_placement_drop rejects mouse move event type");
        check(!sed::ui::viewport::isThingPlacementTemplateDropEvent(QEvent::Resize), "thing_placement_drop rejects resize event type");
